package com.jobmatcher.dto;import jakarta.validation.constraints.*;public class AuthDtos { public record Signup(@NotBlank @Size(max=100) String name,@NotBlank @Email String email,@NotBlank @Size(min=6,max=100) String password,@NotBlank String qualification,@DecimalMin("0.0") @DecimalMax("40.0") double experience){} public record Login(@NotBlank @Email String email,@NotBlank String password){} public record AuthResponse(String token,UserView user){} public record UserView(Long id,String name,String email,String qualification,double experience,java.util.Set<String> skills){} }
